import{_ as a,o as i,c as t,ag as o}from"./chunks/framework.qXLDknWC.js";const u=JSON.parse('{"title":"CharacterVault 1.0.0","description":"","frontmatter":{},"headers":[],"relativePath":"releases/v1.0.0.md","filePath":"releases/v1.0.0.md"}'),r={name:"releases/v1.0.0.md"};function l(s,e,n,h,d,c){return i(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="charactervault-1-0-0" tabindex="-1">CharacterVault 1.0.0 <a class="header-anchor" href="#charactervault-1-0-0" aria-label="Permalink to &quot;CharacterVault 1.0.0&quot;">​</a></h1><p><strong>First stable release.</strong> CharacterVault is a browser-only app for creating, editing, and organizing SillyTavern-compatible character cards (V2/V3). Data stays in your browser via IndexedDB. No account is required for core use.</p><p><strong>Try it:</strong> <a href="https://spaceman2408.github.io/CharacterVault" target="_blank" rel="noreferrer">https://spaceman2408.github.io/CharacterVault</a><br><strong>Docs:</strong> <a href="https://spaceman2408.github.io/CharacterVault/docs/" target="_blank" rel="noreferrer">https://spaceman2408.github.io/CharacterVault/docs/</a></p><hr><h2 id="highlights" tabindex="-1">Highlights <a class="header-anchor" href="#highlights" aria-label="Permalink to &quot;Highlights&quot;">​</a></h2><h3 id="fresh-ui" tabindex="-1">Fresh UI <a class="header-anchor" href="#fresh-ui" aria-label="Permalink to &quot;Fresh UI&quot;">​</a></h3><ul><li>Full visual refresh across the vault, editor, settings, and AI Creation Studio</li><li>Softer palette, cleaner cards, and consistent semantic theme tokens (including a VS Code Dark+ style dark theme)</li><li>Settings pickers and sheets feel smoother, especially on phones</li><li>Layout is clearer without changing the core workflow</li></ul><h3 id="ai-context-and-orion" tabindex="-1">AI Context and Orion <a class="header-anchor" href="#ai-context-and-orion" aria-label="Permalink to &quot;AI Context and Orion&quot;">​</a></h3><ul><li><strong>AI Context</strong> panel streamlined: pin card sections from one list, selected chips, compact token usage</li><li>Context no longer auto-follows the open editor tab. You choose what Orion and the AI toolbar receive</li><li>Pins save and restore across sessions; Clear all truly empties context</li><li>Optional chip to include the section you are currently editing</li><li><strong>Ask Orion</strong> refreshed: clearer empty state, live context status strip, cleaner composer</li><li>Response stats (TTFT, speed, model) on hover or tap, without clipping long model names</li><li>Leaner memory use while chatting: context is resolved only when you send, and streaming buffers are freed after each reply</li></ul><h3 id="editor-ai" tabindex="-1">Editor AI <a class="header-anchor" href="#editor-ai" aria-label="Permalink to &quot;Editor AI&quot;">​</a></h3><ul><li><strong>Ghost preview:</strong> Enhance, Rephrase, Custom, and polish tools show suggestions as soft ghost text on your selection</li><li>Accept / Reject from the strip, <code>Ctrl+Enter</code> / <code>Cmd+Enter</code>, or Escape</li><li>Thinking stays collapsed unless you open it</li><li>Typing is paused during suggestions; saves wait until Accept, Reject, or cancel</li><li><strong>Payload preview</strong> (<code>{ }</code> on the toolbar): inspect the full request body before anything is sent, switch tools, copy, no network call</li></ul><h3 id="per-tool-models" tabindex="-1">Per-tool models <a class="header-anchor" href="#per-tool-models" aria-label="Permalink to &quot;Per-tool models&quot;">​</a></h3><ul><li>Assign a different model (and provider / base URL) to each toolbar tool under <strong>Settings → Prompts</strong></li><li>Unmapped tools keep using the global AI Config model</li><li>Custom prompt mapping also drives Lorebook AI trigger-key generation</li><li>Orion and AI Creation Studio still use the main model from AI Config</li></ul><h3 id="nanogpt-and-reasoning" tabindex="-1">NanoGPT and reasoning <a class="header-anchor" href="#nanogpt-and-reasoning" aria-label="Permalink to &quot;NanoGPT and reasoning&quot;">​</a></h3><ul><li><strong>Sign in with NanoGPT</strong> (PKCE) from AI Config, with models fetched after sign-in</li><li>Account card: balance, subscription status, and weekly usage when available</li><li>Expanded reasoning effort ladder (Minimal through Max / Extra high), with request repair when a provider rejects a value</li><li>Sampler context length up to <strong>1M</strong> tokens, plus smarter packing of large lorebooks and greeting lists</li></ul><h3 id="vault-and-library" tabindex="-1">Vault and library <a class="header-anchor" href="#vault-and-library" aria-label="Permalink to &quot;Vault and library&quot;">​</a></h3><ul><li>Backup the whole library as a ZIP</li><li>Bulk import and drag-and-drop PNG/JSON</li><li>Sort by name or recent; search by name and tags</li><li>Active / total token estimates on cards</li><li>Quick PNG or JSON export from card actions</li><li>Streamed exports and lighter memory behavior for large collections</li></ul><h3 id="mobile" tabindex="-1">Mobile <a class="header-anchor" href="#mobile" aria-label="Permalink to &quot;Mobile&quot;">​</a></h3><ul><li>Greetings and Lorebook use the full screen instead of a short half panel</li><li>Model and provider pickers as searchable bottom sheets</li><li>Improved touch targets, list cards, and panel chrome</li></ul><h3 id="other-capabilities-stable-platform" tabindex="-1">Other capabilities (stable platform) <a class="header-anchor" href="#other-capabilities-stable-platform" aria-label="Permalink to &quot;Other capabilities (stable platform)&quot;">​</a></h3><ul><li>Full V2/V3 card editing: description, personality, scenario, greetings, lorebook, creator notes, extensions, and more</li><li>Customizable section tabs (show, hide, reorder)</li><li>In-editor spellcheck (English Hunspell, personal dictionary, ignore list)</li><li>Snapshots and section or full-card rollback</li><li>AI Creation Studio for generating cards from concepts or tags</li><li>OpenAI-compatible providers plus NanoGPT; local endpoints welcome</li><li>Import / export PNG and JSON compatible with SillyTavern-style frontends</li></ul><hr><h2 id="notes-and-known-limits" tabindex="-1">Notes and known limits <a class="header-anchor" href="#notes-and-known-limits" aria-label="Permalink to &quot;Notes and known limits&quot;">​</a></h2><ul><li>Orion and AI Creation Studio use the global AI Config model (not per-tool routing)</li><li>Temperature, streaming, and thinking settings remain shared</li><li>Clear AI Settings keeps per-tool model choices and custom prompt text</li><li>Not every model supports every reasoning effort level; CharacterVault maps to the closest available</li><li>Payload preview is best-effort; some optional parameters may still be dropped if a provider rejects them</li><li>NanoGPT account weekly usage / subscription details on self-hosted production may need the optional usage proxy (see docs)</li><li>NanoGPT PKCE sign-in needs popups allowed; reliability on some mobile browsers varies</li></ul><hr><h2 id="upgrade" tabindex="-1">Upgrade <a class="header-anchor" href="#upgrade" aria-label="Permalink to &quot;Upgrade&quot;">​</a></h2><p>This is a client-only web app. Opening the hosted site or rebuilding locally is enough; there is no server migration.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/spaceman2408/CharacterVault</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> CharacterVault</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>Local data in IndexedDB from earlier builds should continue to work. If anything looks off after a major UI change, try a hard refresh.</p><hr><h2 id="license" tabindex="-1">License <a class="header-anchor" href="#license" aria-label="Permalink to &quot;License&quot;">​</a></h2><p>GPL-3.0-only</p><p>Thanks for using CharacterVault.</p>`,33)])])}const g=a(r,[["render",l]]);export{u as __pageData,g as default};
